sys_script_fix.script:
(function() {
    // Set 'filename' as display field for x_1830514_fm_file
    var gr = new GlideRecord('sys_dictionary');
    gr.addQuery('name', 'x_1830514_fm_file');
    gr.addQuery('element', 'filename');
    gr.query();
    if (gr.next()) {
        gr.setValue('display', true);
        gr.update();
        gs.print('SUCCESS: filename is now the display field for x_1830514_fm_file');
    } else {
        gs.print('ERROR: Could not find filename column on x_1830514_fm_file');
    }

    // Set 'folder_name' as display field for x_1830514_fm_folder
    var gr2 = new GlideRecord('sys_dictionary');
    gr2.addQuery('name', 'x_1830514_fm_folder');
    gr2.addQuery('element', 'folder_name');
    gr2.query();
    if (gr2.next()) {
        gr2.setValue('display', true);
        gr2.update();
        gs.print('SUCCESS: folder_name is now the display field for x_1830514_fm_folder');
    } else {
        gs.print('ERROR: Could not find folder_name column on x_1830514_fm_folder');
    }
})();
